import type { RaisedHand } from "@kurasu/contract/raised-hands";

import type { EndpointError, QueryOptions } from "../../api/api-error.ts";
import { queryKeys } from "../../api/query-keys.ts";
import { useApiQuery } from "../../api/useApiQuery.ts";

export const useAdminRaisedHands = (
  sessionId: string,
  options?: QueryOptions<ReadonlyArray<RaisedHand>, EndpointError<"adminRaisedHands", "list">>,
) =>
  useApiQuery({
    queryKey: queryKeys.adminRaisedHands(sessionId),
    call: (api) => api.adminRaisedHands.list({ query: { sessionId } }),
    options,
  });

  onCancel: () => void;
}

// While the confirmation waits for the API, nothing closes the dialog: the
// teacher sees how it ends, in the dialog itself when it fails.
export const ConfirmDialog = ({
  open,
  title,
  text,
  content,
  confirmIcon = "trash",
  confirmLabel,
  pendingLabel,
  pending = false,
  error,
  onConfirm,
  onCancel,
}: Props) =>
  open ? (
    <Backdrop layer="alert" onClose={onCancel} dismissible={!pending}>
      <div
        role="alertdialog"
        aria-modal="true"
        aria-label={title}
        className="w-[min(420px,100%)] rounded-[22px] bg-window p-6 text-ink shadow-2xl max-[600px]:w-full max-[600px]:rounded-b-none"
      >
        <h4 className="text-xl font-bold">{title}</h4>
        <p className="mt-2 leading-[1.45] text-muted">{text}</p>
        {content}
        {error == null ? null : <InlineError className="mt-4">{error}</InlineError>}
        <div className="mt-4 flex justify-end gap-2">
          <Button variant="pill" disabled={pending} onClick={onCancel}>
            Cancelar
          </Button>
          <Button
            variant="pill-danger"
            pending={pending}
            pendingLabel={pendingLabel}
            onClick={onConfirm}
          >
            {confirmIcon == null ? null : <Icon name={confirmIcon} size={16} />}
            {confirmLabel}
          </Button>
        </div>
      </div>
    </Backdrop>
  ) : null;
import type { Session, SessionSummary } from "@kurasu/contract/sessions";
import { useState } from "react";

import { ConfirmAction } from "../../../ui/ConfirmAction.tsx";
import { SwitchButton } from "../../../ui/SwitchButton.tsx";
import { EnableSessionDialog } from "./EnableSessionDialog.tsx";
import { FeaturedEffects } from "../FeaturedEffects.tsx";
import { updateErrorText, useUpdateSession } from "../useUpdateSession.ts";

interface Props {
  session: Session;
  featured: SessionSummary | undefined;
}

export const EnabledSwitch = ({ session, featured }: Props) => {
  const [isEnabling, setIsEnabling] = useState(false);

  const update = useUpdateSession();

  const enabled = session.enabled === true;

  const toggle = (onClick: () => void) => (
    <SwitchButton
      isOn={enabled}
      disabled={update.isPending}
      onClick={onClick}
      className="mt-4 flex items-center gap-2.5 text-sm"
    >
      <span>{enabled ? "Habilitada" : "Deshabilitada"}</span>
    </SwitchButton>
  );

  if (!enabled) {
    return (
      <>
        {toggle(() => setIsEnabling(true))}
        {isEnabling ? (
          <EnableSessionDialog
            session={session}
            featured={featured}
            onClose={() => setIsEnabling(false)}
          />
        ) : null}
      </>
    );
  }

  return session.featured ? (
    <ConfirmAction
      renderTrigger={toggle}
      title={`¿Deshabilitar "${session.title}"?`}
      text="Es la sesión destacada: al deshabilitarla deja de serlo, y nadie entra a ningún aula hasta que destaques otra."
      content={<FeaturedEffects session={session} />}
      confirmIcon={null}
      confirmLabel="Deshabilitar"
      pendingLabel="Deshabilitando…"
      errorText={updateErrorText}
      onConfirm={() => update.mutateAsync({ id: session.id, change: { enabled: false } })}
    />
  ) : (
    toggle(() => update.mutate({ id: session.id, change: { enabled: false } }))
  );
};
